class TFMTableRelationHierarchyElement
{
    TableName                               tableName;
    FieldName                               tableField;
    TFMTableRelationHierarchyElement        nestedTable;
    FieldName                               relationFieldName;

}

Method.Source:
public void new(str _tableName, FieldName _tableField, FieldName _relationFieldName)
{
    tableName           = _tableName;
    tableField          = _tableField;
    relationFieldName   = _relationFieldName;
}

public TableName parmTableName(TableName _tableName = TableName)
{
    tableName = _tableName;
    return tableName;
}

public FieldName parmRelationFieldName(FieldName _relationFieldName = relationFieldName)
{
    relationFieldName = _relationFieldName;
    return relationFieldName;
}

public TableName endTable()
{
    return nestedTable == null ? tableName : nestedTable.endTable();
}

public anytype findValue(Common _buffer)
{
    Common subTable;
    QueryRun qr;
    if (!nestedTable)
    {
        return _buffer.(fieldName2Id(_buffer.TableId, tableField));
    }

    //Find nested buffer
    qr = TFMGenericDataHelper::getRelatedTableFromspecifiedField(_buffer, tableField,nestedTable.parmTableName(), nestedTable.parmRelationFieldName());
    qr.next();
    subTable = qr.get(tableName2Id(nestedTable.parmTableName()));
    return nestedTable.findValue(subTable);

}
